-- SQL hasil konversi dari Data KKW_Final untuk Web.xlsx
-- Sheet yang digunakan: Data KKW_MCU Asli
-- Sheet 'Keterangan Coding' sengaja tidak dimasukkan.

CREATE DATABASE IF NOT EXISTS `db_kkw` CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE `db_kkw`;

DROP TABLE IF EXISTS `data_mcu`;
CREATE TABLE `data_mcu` (
  `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `no` TEXT NULL,
  `distrik` TEXT NULL,
  `fungsi` TEXT NULL,
  `tipe_pekerjaan` TEXT NULL,
  `umur` TEXT NULL,
  `lingkar_perut` TEXT NULL,
  `tb` TEXT NULL,
  `bb` TEXT NULL,
  `bmi` TEXT NULL,
  `sistolik` TEXT NULL,
  `diastolik` TEXT NULL,
  `hba1c` TEXT NULL,
  `gdp` TEXT NULL,
  `kolesterol` TEXT NULL,
  `ldl` TEXT NULL,
  `hdl` TEXT NULL,
  `trigliserida` TEXT NULL,
  `eritrosit` TEXT NULL,
  `leukosit` TEXT NULL,
  `trombosit` TEXT NULL,
  `spirometri` TEXT NULL,
  `foto_thorax` TEXT NULL,
  `ekg` TEXT NULL,
  `visus_mata` TEXT NULL,
  `audiometri` TEXT NULL,
  `riwayat_alkohol` TEXT NULL,
  `riwayat_merokok` TEXT NULL,
  `riwayat_diabetes` TEXT NULL,
  `skor_kardiovaskular_jakarta` TEXT NULL,
  `frekuensi_olahraga` TEXT NULL,
  `hasil_mcu` TEXT NULL,
  `klasifikasi_mcu` TEXT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

